import { CommonModule, Location } from '@angular/common';
import { Component } from '@angular/core';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { ButtonComponent } from '../../../../../shared/components/button/button.component';
import { BadgeComponent } from '../../../../../shared/components/badge/badge.component';
import { AvatarComponent } from '../../../../../shared/components/avatar/avatar.component';
import { ActivatedRoute, Router } from '@angular/router';
import { PermissionService } from '../../../../services/permission/permission.service';
import { rolePermissionRes } from '../../../../interfaces/permission.interface';
import { CommonfunctionService } from '../../../../../core/utility/commonfunction.service';
import { NgScrollbarModule } from 'ngx-scrollbar';
import { UserPermissionService } from '../../../../../shared/services/user-permission/user-permission.service';

@Component({
  selector: 'app-rolepermission',
  standalone: true,
  imports: [CommonModule, IconComponent, ButtonComponent, BadgeComponent, IconComponent, AvatarComponent, NgScrollbarModule],
  templateUrl: './rolepermission.component.html',
  styleUrl: './rolepermission.component.scss'
})
export class RolepermissionComponent {
  expanded: boolean = false;
  nCaseid: string;
  rolePermissionLs: rolePermissionRes[];
  isloading: boolean = false;
  nRoleid: string;
  constructor(private route: ActivatedRoute, private permissionS: PermissionService, private cf: CommonfunctionService, private location: Location,
    private userPermissions: UserPermissionService
  ) {
    var params = this.route.snapshot.params;
    params = JSON.parse(atob(params["id"]));
    this.nCaseid = params && params["id"] ? params["id"] : 0;
    userPermissions.userPermissionList(this.nCaseid);

  }

  async ngOnInit() {
    this.getPermission();
  }

  async getPermission() {
    this.isloading = true
    this.rolePermissionLs = await this.permissionS.rolePermission(this.nCaseid)
    console.log(this.rolePermissionLs);

    this.isloading = false;
  }

  editPermission(x) {
    this.cf.gotoEncoduri('/permission/editpermission', { id: this.nCaseid, role: x.nRoleid, rnm: x.cRole });
  }

  close() {
    this.location.back();
  }

  manageRole(x) {
    x.cStatus = x.cStatus == 'A' ? 'I' : 'A';
    this.permissionS.manageRole({ nCaseid: this.nCaseid, nRoleid: x.nRoleid, cStatus: x.cStatus });
  }


}
